import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import { ActionUsageSummary } from './action_usage_summary'
import type { ActionUsageScopeStore } from './action_usage_scope_store'

interface ActionUsageSummaryOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    scopeStore: ActionUsageScopeStore
}

/** Subscribes usage summary to conversation and history data only. */
export function ActionUsageSummaryOwner(props: ActionUsageSummaryOwnerProps) {
    const { action, context, conversationStore, historyStore, scopeStore } = props
    const liveConversation = useActionRunSelector(action.id, context, (run) => run?.conversation ?? null)
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const historySnapshot = useSyncExternalStore(historyStore.subscribe, historyStore.getSnapshot, historyStore.getSnapshot)
    const scopeSnapshot = useSyncExternalStore(scopeStore.subscribe, scopeStore.getSnapshot, scopeStore.getSnapshot)
    const displayedConversation = liveConversation ?? conversationSnapshot.selectedConversation
    const scope = displayedConversation ? scopeSnapshot : 'actionCard'

    useEffect(() => {
        void historyStore.load()
    }, [historyStore])

    useEffect(() => {
        if (!displayedConversation) scopeStore.useActionCardScope()
    }, [displayedConversation, scopeStore])

    if (context.kind !== 'card' || !context.file || !context.cardInternalId || action.type !== 'agent') return null

    const handleToggleScope = () => scopeStore.toggle(!!displayedConversation)

    return (
        <ActionUsageSummary
            actionId={action.id}
            cardInternalId={context.cardInternalId}
            conversation={displayedConversation}
            conversations={conversationStore.conversationOptions(liveConversation)}
            history={historySnapshot.entries}
            liveConversation={liveConversation}
            onToggleScope={handleToggleScope}
            scope={scope}
        />
    )
}

import { actionContextIdentity } from '../../data/action_context'
import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { AgentConversation, AgentConversationEntry, AgentConversationEventEntry } from '../../data/data_types'
import type {
    AgentApproval,
    AgentApprovalDecision,
    AgentApprovalRequestId,
    AgentConversationReservation,
    AgentQuestion,
    ActionRunEvent,
    ActionRunStatus,
    ActionRunTerminalStatus,
    ActionRunUpdate,
    ActionRunInput,
    ActionRunLogEntry,
    ActionRunResult,
} from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { ElectronActionBridge } from '../../data/electron_action_bridge'
import { actionService } from './action_service'
import { actionPromptDraftService } from './action_prompt_draft_service'
import { register } from '../service_injector'

const TERMINAL_STATUSES = new Set<ActionRunTerminalStatus>(['cancelled', 'completed', 'failed', 'okButNotAfter'])
const ACTIVE_STATUSES = new Set<ActionRunStatus>(['queued', 'running', 'waitingForInput'])
const EMPTY_ACTIVE_RUNS: ActiveActionRun[] = []

export interface ActionRun {
    activeActionAutoFinish: ActionDefinition['autoFinish']
    activeActionId: string | null
    activeActionStreaming: boolean
    activeActionType: ActionDefinition['type'] | null
    conversation: AgentConversation | null
    context: ActionContext
    runId: string
    logs: ActionRunLogEntry[]
    approvals: LiveAgentApproval[]
    interactionReady: boolean
    question: LiveAgentQuestion | null
    reference: string | null
    rootActionId: string
    status: ActionRunStatus
}

export interface LiveAgentApproval extends AgentApproval {
    submitted: boolean
}

export interface LiveAgentQuestion {
    questions: AgentQuestion[]
    requestId: number | string | null
}

export interface ActiveActionRun {
    rootActionId: string
    runId: string
    status: ActionRunStatus
}

type EventListener = (event: ActionRunEvent) => void
type StoreListener = () => void

function actionName(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.label ?? actionId
}

function actionType(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.type ?? null
}

function actionStreaming(actionId: string) {
    return actionService.getActions().find((action) => action.id === actionId)?.streaming ?? false
}

function createLog(event: ActionRunEvent): ActionRunLogEntry {
    return {
        actionId: event.actionId,
        actionName: actionName(event.actionId),
        command: event.type === 'action' ? event.command ?? null : null,
        message: event.type === 'action' ? event.message ?? `${actionName(event.actionId)} ${event.status}` : `${actionName(event.actionId)} running`,
        phase: event.phase,
        ...(event.type === 'action' && event.permissionMode ? { permissionMode: event.permissionMode } : {}),
        status: event.status,
        stderr: '',
        stdout: '',
        ...(event.type === 'action' && event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),
    }
}

function runningLogIndex(logs: ActionRunLogEntry[], event: ActionRunEvent) {
    return logs.findLastIndex((log) => (
        log.actionId === event.actionId
        && log.phase === event.phase
        && (log.status === 'queued' || log.status === 'running')
    ))
}

type AgentOutputUpdate = Pick<
    Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,
    'content' | 'previousContent' | 'replace'
>

function updatedStdout(currentStdout: string, update: AgentOutputUpdate) {
    if (!update.replace) return `${currentStdout}${update.content}`
    if (update.previousContent === undefined) throw new Error('Missing previous assistant output')
    if (!currentStdout.endsWith(update.previousContent)) throw new Error('Assistant output replacement is out of order')

    return `${currentStdout.slice(0, currentStdout.length - update.previousContent.length)}${update.content}`
}

function updateActionLogs(logs: ActionRunLogEntry[], event: Extract<ActionRunEvent, { type: 'action' }>) {
    const currentIndex = runningLogIndex(logs, event)
    if (currentIndex < 0) return [...logs, createLog(event)]
    const current = logs[currentIndex]
    const next = [...logs]
    next[currentIndex] = {
        ...current,
        command: event.command ?? current.command,
        message: event.message ?? `${actionName(event.actionId)} ${event.status}`,
        ...(event.permissionMode ? { permissionMode: event.permissionMode } : {}),
        status: event.status,
        ...(event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),
    }

    return next
}

function updateOutputLogs(
    logs: ActionRunLogEntry[],
    event: Extract<ActionRunEvent, { type: 'update' }>,
    update: Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,
) {
    const currentIndex = logs.findLastIndex((log) => (
        log.actionId === event.actionId && log.phase === event.phase && log.status === 'running'
    ))
    const current = currentIndex >= 0 ? logs[currentIndex] : createLog(event)
    const updated = {
        ...current,
        command: update.command ?? current.command,
        stderr: update.kind === 'error' ? `${current.stderr}${update.content}` : current.stderr,
        stdout: update.kind === 'output' ? updatedStdout(current.stdout, update) : current.stdout,
    }
    if (currentIndex < 0) return [...logs, updated]
    const next = [...logs]
    next[currentIndex] = updated

    return next
}

function eventIdentity(event: AgentConversationEventEntry) {
    return event.providerItemId ?? event.id
}

function upsertAgentEvent(entries: AgentConversationEntry[], event: AgentConversationEventEntry) {
    const identity = eventIdentity(event)
    const currentIndex = entries.findIndex((entry) => entry.kind === 'event' && eventIdentity(entry) === identity)
    if (currentIndex < 0) return [...entries, event]

    const current = entries[currentIndex]
    const next = [...entries]
    next[currentIndex] = {
        ...event,
        ...(event.sequence === undefined && current.sequence !== undefined ? { sequence: current.sequence } : {}),
    }

    return next
}

function nextConversationSequence(conversation: AgentConversation) {
    const sequences = conversation.entries.map(({ sequence }) => sequence)
        .filter((sequence): sequence is number => sequence !== undefined)

    return sequences.length > 0 ? Math.max(...sequences) + 1 : undefined
}

function appendAssistantMessage(
    conversation: AgentConversation,
    update: { content: string, messageId?: string, replace?: boolean, sequence?: number },
) {
    const sequence = update.sequence ?? nextConversationSequence(conversation)
    const latestUserIndex = conversation.entries.findLastIndex((entry) => entry.kind === 'message' && entry.role === 'user')
    const currentAssistantMessage = conversation.entries.slice(latestUserIndex + 1)
        .findLast((entry) => entry.kind === 'message' && entry.role === 'assistant')
    const messageId = update.messageId
        ?? currentAssistantMessage?.id
        ?? `${conversation.id}-assistant-${sequence ?? conversation.entries.length + 1}`
    const currentIndex = conversation.entries.findIndex((entry) => entry.kind === 'message' && entry.id === messageId)
    const entries: AgentConversationEntry[] = currentIndex < 0
        ? [...conversation.entries, {
            content: update.content,
            id: messageId,
            kind: 'message',
            role: 'assistant' as const,
            ...(sequence !== undefined ? { sequence } : {}),
            timestamp: conversation.startedAt,
        }]
        : conversation.entries.map((entry, index) => index === currentIndex
            ? { ...entry, content: update.replace ? update.content : `${entry.content}${update.content}` }
            : entry)

    return { ...conversation, entries }
}

function conversationStatus(status: ActionRunStatus): AgentConversation['status'] {
    if (status === 'queued') return 'running'
    if (status === 'okButNotAfter') return 'completed'

    return status
}

function contextKey(context: ActionContext) {
    return actionContextIdentity(context)
}

export async function cancelActionRun(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Action cancellation requires Electron')

    await bridge.cancelActionRun(runId)
}

export async function sendActionMessage(runId: string, content: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.sendActionMessage) throw new Error('Streaming agent messaging requires Electron')

    await bridge.sendActionMessage(runId, content)
}

export async function answerActionQuestion(
    runId: string,
    requestId: number | string | null,
    answers: Record<string, string[]>,
) {
    const bridge = getElectronActionBridge()
    if (!bridge?.answerActionQuestion) throw new Error('Streaming agent questions require Electron')

    await bridge.answerActionQuestion(runId, requestId, answers)
}

export async function answerActionApproval(
    runId: string,
    requestId: AgentApprovalRequestId,
    decision: AgentApprovalDecision,
) {
    const bridge = getElectronActionBridge()
    if (!bridge?.answerActionApproval) throw new Error('Streaming agent approvals require Electron')

    await bridge.answerActionApproval(runId, requestId, decision)
}

export async function finishActionRun(runId: string) {
    const bridge = getElectronActionBridge()
    if (!bridge?.finishActionRun) throw new Error('Finishing a streaming agent requires Electron')

    await bridge.finishActionRun(runId)
}

export async function notifyActionCardStateChange(cardInternalId: string | null, state: string) {
    if (!cardInternalId) return
    const bridge = getElectronActionBridge()
    if (!bridge?.notifyActionCardStateChange) throw new Error('Automatic agent finish requires Electron')

    await bridge.notifyActionCardStateChange(cardInternalId, state)
}

/** Stable state owner for one action run. */
export class ActionRunStore {
    private readonly listeners = new Set<StoreListener>()
    private readonly onReleased: (store: ActionRunStore) => void
    private snapshot: ActionRun

    constructor(snapshot: ActionRun, onReleased: (store: ActionRunStore) => void) {
        this.onReleased = onReleased
        this.snapshot = snapshot
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: StoreListener) => {
        this.listeners.add(listener)

        return () => {
            this.listeners.delete(listener)
            this.onReleased(this)
        }
    }

    hasConsumers() {
        return this.listeners.size > 0
    }

    update(snapshot: ActionRun) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

function actionContextKey(actionId: string, context: ActionContext) {
    return `${actionId}\u0000${contextKey(context)}`
}

function activeRun(run: ActionRun): ActiveActionRun {
    return { rootActionId: run.rootActionId, runId: run.runId, status: run.status }
}

function sameActiveRuns(first: ActiveActionRun[], second: ActiveActionRun[]) {
    return first.length === second.length && first.every(({ runId, status }, index) => (
        second[index]?.runId === runId && second[index]?.status === status
    ))
}

function publishKey(map: Map<string, Set<StoreListener>>, key: string) {
    const listeners = map.get(key) ?? []
    for (const listener of listeners) listener()
}

function publishListeners(map: Map<string, Set<StoreListener>>) {
    for (const listeners of map.values()) {
        for (const listener of listeners) listener()
    }
}

/** Owns one renderer-wide bridge subscription and routes events to scoped run stores. */
export class ActionRunRegistry extends EventTarget {
    private readonly actionContextListeners = new Map<string, Set<StoreListener>>()
    private readonly actionContextStores = new Map<string, ActionRunStore>()
    private readonly activeRunEventListeners = new Set<EventListener>()
    private readonly contextActiveListeners = new Map<string, Set<StoreListener>>()
    private readonly contextActiveSnapshots = new Map<string, ActiveActionRun[]>()
    private readonly contextEventListeners = new Map<string, Set<EventListener>>()
    private eventSequences = new Map<string, number>()
    private readonly globalActiveListeners = new Set<StoreListener>()
    private globalActiveSnapshot: ActiveActionRun[] = EMPTY_ACTIVE_RUNS
    private recoveryEvents: ActionRunEvent[] | null = null
    private runs = new Map<string, ActionRunStore>()
    private subscribedBridge: ElectronActionBridge | null = null
    private startsInProgress = 0
    private readonly terminalResults = new Map<string, ActionRunResult>()
    private unsubscribeBridge: (() => void) | null = null
    private readonly waiters = new Map<string, Set<(result: ActionRunResult) => void>>()

    constructor() {
        super()
        register('actionRunRegistry', this)
    }

    start() {
        const bridge = getElectronActionBridge()
        if (!bridge) return
        if (this.unsubscribeBridge && bridge === this.subscribedBridge) return

        this.unsubscribeBridge?.()
        this.subscribedBridge = bridge
        this.recoveryEvents = bridge.loadActiveActionRunEvents ? [] : null
        this.unsubscribeBridge = bridge.onActionRun((event) => this.handleIncomingEvent(event))
        if (bridge.loadActiveActionRunEvents) void this.recoverActiveRuns(bridge)
    }

    stop() {
        this.unsubscribeBridge?.()
        this.subscribedBridge = null
        this.unsubscribeBridge = null
        this.eventSequences = new Map()
        this.recoveryEvents = null
        this.runs = new Map()
        this.actionContextStores.clear()
        this.contextActiveSnapshots.clear()
        this.publishGlobalActive([])
        publishListeners(this.actionContextListeners)
        publishListeners(this.contextActiveListeners)
    }

    getRunStore(runId: string) {
        return this.runs.get(runId) ?? null
    }

    getActionRunStore(actionId: string, context: ActionContext) {
        return this.getActionRunStoreByKey(actionId, contextKey(context))
    }

    getActionRunStoreByKey(actionId: string, contextIdentity: string) {
        return this.actionContextStores.get(`${actionId}\u0000${contextIdentity}`) ?? null
    }

    getContextActiveSnapshot(context: ActionContext) {
        return this.getContextActiveSnapshotByKey(contextKey(context))
    }

    getContextActiveSnapshotByKey(contextIdentity: string) {
        return this.contextActiveSnapshots.get(contextIdentity) ?? EMPTY_ACTIVE_RUNS
    }

    getGlobalActiveSnapshot = () => this.globalActiveSnapshot

    subscribeActionRun(actionId: string, context: ActionContext, listener: StoreListener) {
        return this.subscribeActionRunByKey(actionId, contextKey(context), listener)
    }

    subscribeActionRunByKey(actionId: string, contextIdentity: string, listener: StoreListener) {
        const key = `${actionId}\u0000${contextIdentity}`
        const unsubscribe = this.subscribeMap(this.actionContextListeners, key, listener)

        return () => {
            unsubscribe()
            const store = this.actionContextStores.get(key)
            if (store) this.releaseTerminalRun(store.getSnapshot().runId)
        }
    }

    subscribeContextActive(context: ActionContext, listener: StoreListener) {
        return this.subscribeContextActiveByKey(contextKey(context), listener)
    }

    subscribeContextActiveByKey(contextIdentity: string, listener: StoreListener) {
        return this.subscribeMap(this.contextActiveListeners, contextIdentity, listener)
    }

    subscribeContextEvents(context: ActionContext, listener: EventListener) {
        return this.subscribeMap(this.contextEventListeners, contextKey(context), listener)
    }

    subscribeActiveRunEvents(listener: EventListener) {
        this.activeRunEventListeners.add(listener)
        this.start()

        return () => this.activeRunEventListeners.delete(listener)
    }

    readonly subscribeGlobalActive = (listener: StoreListener) => {
        this.globalActiveListeners.add(listener)
        this.start()

        return () => this.globalActiveListeners.delete(listener)
    }

    async startRun(
        action: ActionDefinition,
        context: ActionContext,
        runInput: ActionRunInput = {},
        onStarted?: (runId: string) => void,
        interactive = true,
        conversationReservation?: AgentConversationReservation,
    ) {
        const bridge = getElectronActionBridge()
        if (!bridge) throw new Error('Action run requires Electron')
        this.start()
        const start = interactive ? bridge.startAction.bind(bridge) : bridge.startUnattendedAction?.bind(bridge)
        if (!start) throw new Error('Unattended action run requires Electron')
        this.startsInProgress += 1
        let runId: string
        try {
            runId = await start({ actionId: action.id, ...(conversationReservation ? { conversationReservation } : {}), context, runInput })
        } finally {
            this.startsInProgress -= 1
        }
        onStarted?.(runId)

        return this.waitForRun(runId)
    }

    async restartRun(
        previousRunId: string,
        action: ActionDefinition,
        context: ActionContext,
        runInput: ActionRunInput,
        onStarted?: (runId: string) => void,
    ) {
        const bridge = getElectronActionBridge()
        if (!bridge?.restartActionRun) throw new Error('Restarting an action run requires Electron')
        this.start()
        this.startsInProgress += 1
        let runId: string
        try {
            runId = await bridge.restartActionRun(previousRunId, { actionId: action.id, context, runInput })
        } finally {
            this.startsInProgress -= 1
            this.terminalResults.delete(previousRunId)
        }
        onStarted?.(runId)

        return this.waitForRun(runId)
    }

    private waitForRun(runId: string): Promise<ActionRunResult> {
        const terminalResult = this.terminalResults.get(runId)
        if (terminalResult) {
            this.terminalResults.delete(runId)

            return Promise.resolve(terminalResult)
        }
        const current = this.runs.get(runId)?.getSnapshot()
        if (current && TERMINAL_STATUSES.has(current.status as ActionRunTerminalStatus)) {
            const result = { logs: current.logs, status: current.status as ActionRunTerminalStatus }
            this.releaseTerminalRun(runId)

            return Promise.resolve(result)
        }

        return new Promise((resolve) => {
            const waiters = this.waiters.get(runId) ?? new Set()
            waiters.add(resolve)
            this.waiters.set(runId, waiters)
        })
    }

    private async recoverActiveRuns(bridge: ElectronActionBridge) {
        try {
            const events = await bridge.loadActiveActionRunEvents?.() ?? []
            if (this.subscribedBridge !== bridge || !this.recoveryEvents) return
            const recoveryEvents = this.recoveryEvents
            this.recoveryEvents = null
            for (const event of events) this.handleEvent(event)
            for (const event of recoveryEvents) this.handleEvent(event)
        } catch (error) {
            if (this.subscribedBridge !== bridge) return
            const recoveryEvents = this.recoveryEvents ?? []
            this.recoveryEvents = null
            for (const event of recoveryEvents) this.handleEvent(event)
            this.dispatchEvent(new CustomEvent('recoveryFailed', { detail: error }))
        }
    }

    private handleIncomingEvent(event: ActionRunEvent) {
        if (this.recoveryEvents) {
            this.recoveryEvents.push(event)
            return
        }

        this.handleEvent(event)
    }

    private handleEvent(event: ActionRunEvent) {
        if (event.sequence !== undefined) {
            const currentSequence = this.eventSequences.get(event.runId) ?? 0
            if (event.sequence <= currentSequence) return
            this.eventSequences.set(event.runId, event.sequence)
        }
        const store = this.runs.get(event.runId)
        const current = store?.getSnapshot() ?? {
            activeActionAutoFinish: null,
            activeActionId: null,
            activeActionStreaming: false,
            activeActionType: null,
            conversation: null,
            approvals: [],
            context: event.context,
            runId: event.runId,
            logs: [],
            interactionReady: false,
            question: null,
            reference: null,
            rootActionId: event.rootActionId,
            status: 'running' as const,
        }
        let next = { ...current, context: event.context, rootActionId: event.rootActionId }
        if (event.type === 'run') next = { ...next, status: event.status }
        if (event.type === 'run' && TERMINAL_STATUSES.has(event.status as ActionRunTerminalStatus)) {
            next = { ...next, approvals: [], question: null }
            actionPromptDraftService.clearRunDrafts(event.runId)
        }
        if (event.type === 'agentState') next = { ...next, status: event.status }
        if (event.type === 'action') {
            const active = event.status === 'queued' || event.status === 'running'
            const activeType = event.actionType ?? actionType(event.actionId)
            next = {
                ...next,
                activeActionAutoFinish: active ? event.autoFinish ?? null : null,
                activeActionId: active ? event.actionId : null,
                activeActionStreaming: active && (event.streaming ?? actionStreaming(event.actionId)),
                activeActionType: active ? activeType : null,
                interactionReady: active && !!event.interactionReady,
                logs: updateActionLogs(next.logs, event),
                reference: event.reference ?? next.reference,
            }
            if (active) next.status = event.status
            if (!active) actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
        }
        if (event.type === 'agentState') {
            next = {
                ...next,
                activeActionAutoFinish: event.autoFinish ?? null,
                activeActionId: event.actionId,
                activeActionStreaming: event.streaming ?? actionStreaming(event.actionId),
                activeActionType: event.actionType ?? actionType(event.actionId),
                conversation: next.conversation
                    ? { ...next.conversation, completedAt: null, status: event.status }
                    : null,
                interactionReady: event.interactionReady ?? true,
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentStarted') {
            const { continued } = event.update
            next = { ...next, conversation: event.update.conversation }
            if (continued) actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
        }
        if (event.type === 'update' && event.update.kind === 'agentClosed') {
            next = { ...next, conversation: event.update.conversation }
        }
        if (event.type === 'update' && event.update.kind === 'agentEvent' && next.conversation) {
            next = {
                ...next,
                conversation: {
                    ...next.conversation,
                    entries: upsertAgentEvent(next.conversation.entries, event.update.event),
                },
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentQuestion') {
            next = {
                ...next,
                question: { questions: event.update.questions, requestId: event.update.requestId },
                status: 'waitingForInput',
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApproval') {
            const requestId = event.update.approval.requestId
            const approvals = next.approvals.filter((approval) => approval.requestId !== requestId)
            next = {
                ...next,
                approvals: [...approvals, { ...event.update.approval, submitted: false }],
                status: 'waitingForInput',
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApprovalSubmitted') {
            const { requestId } = event.update
            next = {
                ...next,
                approvals: next.approvals.map((approval) => approval.requestId === requestId
                    ? { ...approval, submitted: true }
                    : approval),
            }
        }
        if (event.type === 'update' && event.update.kind === 'agentApprovalResolved') {
            const { requestId } = event.update
            const approvals = next.approvals.filter((approval) => approval.requestId !== requestId)
            next = {
                ...next,
                approvals,
                status: next.question || approvals.length > 0 ? 'waitingForInput' : event.status,
            }
        }
        if (
            event.type === 'update'
            && (event.update.kind === 'agentUserMessage' || event.update.kind === 'agentQuestionAnswer')
            && next.conversation
        ) {
            next = {
                ...next,
                conversation: {
                    ...next.conversation,
                    entries: [...next.conversation.entries, event.update.userMessage],
                },
                question: null,
                status: next.approvals.length > 0 ? 'waitingForInput' : event.status,
            }
            if (event.update.kind === 'agentUserMessage') {
                actionPromptDraftService.clearRunDraft(event.runId, event.actionId)
            }
        }
        if (event.type === 'update' && (event.update.kind === 'output' || event.update.kind === 'error')) {
            const conversation = event.update.kind === 'output' && next.conversation
                ? appendAssistantMessage(next.conversation, event.update)
                : next.conversation
            next = { ...next, conversation, logs: updateOutputLogs(next.logs, event, event.update) }
        }
        if (event.type === 'update' && event.update.kind !== 'agentClosed' && next.conversation) {
            next = {
                ...next,
                conversation: { ...next.conversation, status: conversationStatus(event.status) },
            }
        }
        const nextStore = store ?? new ActionRunStore(next, (releasedStore) => this.handleStoreReleased(releasedStore))
        if (!store) {
            this.runs.set(event.runId, nextStore)
            const bindingKey = actionContextKey(event.rootActionId, event.context)
            this.actionContextStores.set(bindingKey, nextStore)
            publishKey(this.actionContextListeners, bindingKey)
        } else nextStore.update(next)

        this.publishActiveIndexes(contextKey(current.context), contextKey(next.context))
        this.publishScopedEvents(event)
        if (event.type === 'run' && TERMINAL_STATUSES.has(event.status as ActionRunTerminalStatus)) {
            this.resolveWaiters(next)
            this.releaseTerminalRun(event.runId)
        }
    }

    private publishActiveIndexes(previousContextKey: string, nextContextKey: string) {
        const affectedContextKeys = new Set([previousContextKey, nextContextKey])
        for (const affectedContextKey of affectedContextKeys) {
            const nextSnapshot = [...this.runs.values()]
                .map((store) => store.getSnapshot())
                .filter((run) => contextKey(run.context) === affectedContextKey && ACTIVE_STATUSES.has(run.status))
                .map(activeRun)
            const currentSnapshot = this.contextActiveSnapshots.get(affectedContextKey) ?? []
            if (sameActiveRuns(currentSnapshot, nextSnapshot)) continue

            if (nextSnapshot.length > 0) this.contextActiveSnapshots.set(affectedContextKey, nextSnapshot)
            else this.contextActiveSnapshots.delete(affectedContextKey)
            publishKey(this.contextActiveListeners, affectedContextKey)
        }
        const nextGlobalSnapshot = [...this.runs.values()]
            .map((store) => store.getSnapshot())
            .filter((run) => ACTIVE_STATUSES.has(run.status))
            .map(activeRun)
        if (!sameActiveRuns(this.globalActiveSnapshot, nextGlobalSnapshot)) this.publishGlobalActive(nextGlobalSnapshot)
    }

    private publishScopedEvents(event: ActionRunEvent) {
        const listeners = this.contextEventListeners.get(contextKey(event.context)) ?? []
        for (const listener of listeners) listener(event)
        for (const listener of this.activeRunEventListeners) listener(event)
    }

    private resolveWaiters(run: ActionRun) {
        const waiters = this.waiters.get(run.runId)
        this.waiters.delete(run.runId)
        const result = { logs: run.logs, status: run.status as ActionRunTerminalStatus }
        if (!waiters && this.startsInProgress > 0) this.terminalResults.set(run.runId, result)
        for (const resolve of waiters ?? []) resolve(result)
    }

    private handleStoreReleased(store: ActionRunStore) {
        const { runId, status } = store.getSnapshot()
        if (TERMINAL_STATUSES.has(status as ActionRunTerminalStatus)) this.releaseTerminalRun(runId)
    }

    private releaseTerminalRun(runId: string) {
        const store = this.runs.get(runId)
        if (!store || store.hasConsumers() || this.waiters.has(runId)) return

        const run = store.getSnapshot()
        const bindingKey = actionContextKey(run.rootActionId, run.context)
        if ((this.actionContextListeners.get(bindingKey)?.size ?? 0) > 0) return

        this.runs.delete(runId)
        this.eventSequences.delete(runId)
        if (this.actionContextStores.get(bindingKey) === store) {
            this.actionContextStores.delete(bindingKey)
            publishKey(this.actionContextListeners, bindingKey)
        }
    }

    private subscribeMap<T>(map: Map<string, Set<T>>, key: string, listener: T) {
        const listeners = map.get(key) ?? new Set<T>()
        listeners.add(listener)
        map.set(key, listeners)
        this.start()

        return () => {
            listeners.delete(listener)
            if (listeners.size === 0) map.delete(key)
        }
    }

    private publishGlobalActive(snapshot: ActiveActionRun[]) {
        this.globalActiveSnapshot = snapshot
        for (const listener of this.globalActiveListeners) listener()
    }
}

export const actionRunRegistry = new ActionRunRegistry()

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.turnStarted = true;
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) run.conversation.usage = accumulateUsage(run.conversation.usage, event.usage);
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
};

module.exports = { STREAMING_EVENT_HANDLERS };

const crypto = require('node:crypto');
const path = require('node:path');
const crossSpawn = require('cross-spawn');

const {
    accumulateUsage,
    createConversation,
    createEventEntry,
    createMessageEntry,
    updateProviderSession,
} = require('./agent_conversation');
const {
    conversationReference,
    persistConversation,
    persistConversationCheckpoint,
} = require('./agent_conversation_persistence');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { diagnoseCodexCacheError, isCodexCacheError } = require('./agent_codex_cache_diagnostic');
const { logAgentEvent } = require('./agent_file_logger');
const agentInteractions = require('./agent_run_interactions');
const {
    attachRunProtocol,
    createRun,
    createRunResult,
    emitRunEvent,
} = require('./agent_run_state');
const {
    appendAssistantOutput,
    completeAssistantOutput,
    lastMessageEntry,
    nextConversationSequence,
    nextRunSequence,
} = require('./agent_run_transcript');
const {
    readOptionalString,
    requireCommand,
    requireProjectFolder,
    requireString,
} = require('./agent_run_validation');
const { redactSecrets } = require('./agent_secret_redaction');
const { filterCompleteStderrLines, isHiddenStderrLine } = require('./agent_stderr_filter');
const { STREAMING_EVENT_HANDLERS } = require('./agent_streaming_event_handlers');
const { terminateProcessTree } = require('../process_tree');
const { assertGitRoot, ensureInsideRoot, requireRootPath } = require('../../git/git_commands');

const AGENT_FINISH_GRACE_MS = 5_000;

class AgentRunnerService {
    constructor(dependencies = {}) {
        this.codexRuntimeService = dependencies.codexRuntimeService ?? null;
        this.persistConversation = dependencies.persistConversation
            ?? dependencies.persistTerminalConversation
            ?? persistConversation;
        this.persistConversationCheckpoint = dependencies.persistConversationCheckpoint
            ?? persistConversationCheckpoint;
        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
        this.diagnoseCodexCacheError = dependencies.diagnoseCodexCacheError ?? diagnoseCodexCacheError;
        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
        this.setTimeout = dependencies.setTimeout ?? setTimeout;
        this.terminateProcessTree = dependencies.terminateProcessTree ?? terminateProcessTree;
        this.handleFinishTimeout = this.handleFinishTimeout.bind(this);
        this.processes = new Map();
        this.runningConversationIds = new Set();
    }

    async run(project, request, onEvent) {
        let resolveCompletion;
        let rejectCompletion;
        const completion = new Promise((resolve, reject) => {
            resolveCompletion = resolve;
            rejectCompletion = reject;
        });
        const onComplete = (exitCode, run) => resolveCompletion(createRunResult(request, exitCode, run));
        const onCompletionError = (error) => rejectCompletion(error);

        await this.start(project, request, onEvent, onComplete, onCompletionError);

        return completion;
    }

    async start(project, requestValue, onEvent, onComplete, onCompletionError) {
        const request = {
            activityOrigin: { kind: 'project' },
            activityProject: project,
            ...requestValue,
        };
        const rootPath = requireRootPath(project);
        await assertGitRoot(rootPath);
        const command = requireCommand(request?.command);
        readOptionalString(request?.actionId, 'actionId');
        const cardPath = readOptionalString(request?.cardPath, 'cardPath');
        const prompt = requireString(request?.prompt, 'prompt');
        const agent = requireString(request?.agent ?? 'generic', 'agent');
        const streaming = request.streaming === true;
        requireProjectFolder(request?.projectFolder);
        if (cardPath) ensureInsideRoot(rootPath, path.join(rootPath, cardPath));

        const id = `agent-turn-${crypto.randomUUID()}`;
        const startedAt = new Date().toISOString();
        const conversationId = request.conversation?.id ?? request.conversationId ?? `agent-${crypto.randomUUID()}`;
        const reference = request.reference ?? conversationReference(request, conversationId);
        const conversation = createConversation(request, conversationId, startedAt, reference);
        let nextSequence = nextConversationSequence(conversation);
        if (this.runningConversationIds.has(conversation.id)) throw new Error(`Agent conversation already has a running turn: ${conversation.id}`);
        const lastMessage = lastMessageEntry(conversation);
        if (request.reuseLastUserMessage) {
            if (lastMessage?.role !== 'user' || lastMessage.content !== prompt) throw new Error('Missing failed-turn user message for agent retry');
        } else {
            conversation.entries.push(createMessageEntry(`${id}-user`, 'user', prompt, startedAt, undefined, nextSequence));
            nextSequence += 1;
        }
        const [configuredExecutable, ...configuredArguments] = command;
        const environment = createAgentEnvironment(process.env);
        const resolvedExecutable = await this.executableResolver.find(configuredExecutable, { cwd: rootPath, env: environment });
        const executable = resolvedExecutable ?? configuredExecutable;
        const argumentsList = streaming ? configuredArguments : [...configuredArguments, prompt];
        const child = crossSpawn(executable, argumentsList, {
            cwd: rootPath,
            detached: process.platform !== 'win32',
            env: environment,
            stdio: ['pipe', 'pipe', 'pipe'],
            // windowsHide: true,
        });
        logAgentEvent('[agent:start]', {
            arguments: configuredArguments,
            cwd: rootPath,
            actionRunId: request.actionRunId ?? null,
            executable,
            pid: child.pid,
            runId: id,
            startedAt,
        });
        const run = createRun({
            agent,
            child,
            conversation,
            environment,
            executable,
            id,
            nextSequence,
            onComplete,
            onCompletionError,
            onEvent,
            reference,
            request,
            startedAt,
            streaming,
        });
        attachRunProtocol(run, {
            onCodexRuntimeEvent: (event) => this.handleCodexRuntimeEvent(event),
            onMalformedOutput: (line) => this.handleMalformedOutput(id, line),
            onProviderEvent: (event) => this.handleProviderEvent(id, event),
            onStreamingEvent: (event) => this.handleStreamingEvent(id, event),
            onStreamingLine: (line) => this.handleStreamingLine(id, line),
            providerConversationId: request.providerConversationId,
            rootPath,
        });
        this.processes.set(id, run);
        this.runningConversationIds.add(conversation.id);

        child.stdout.on('data', (chunk) => this.handleOutput(id, 'stdout', chunk));
        child.stderr.on('data', (chunk) => this.handleOutput(id, 'stderr', chunk));
        child.on('error', (error) => this.handleError(id, error));
        child.stdin.on('error', (error) => this.handleError(id, error));
        child.on('close', (exitCode) => {
            void this.handleClose(id, exitCode ?? 1).finally(run.resolveClosed);
        });
        if (streaming) {
            const initialPrompt = typeof request.contextInput === 'string' && request.contextInput.length > 0
                ? `${request.contextInput}\n\n[User]\n\n${prompt}`
                : prompt;
            try {
                await run.streamingAdapter.start(initialPrompt);
            } catch (error) {
                this.failStreamingRun(run, error);
            }
        } else {
            if (typeof request.contextInput === 'string' && request.contextInput.length > 0) child.stdin.write(request.contextInput);
            child.stdin.end();
        }
        const userMessage = lastMessageEntry(conversation);
        if (!userMessage || userMessage.role !== 'user') throw new Error('Missing current agent user message');
        emitRunEvent(run, {
            continued: !!request.conversation,
            conversation: structuredClone(conversation),
            type: 'started',
        });

        return { conversation: structuredClone(conversation), reference, runId: id };
    }

    stop(runId) {
        const run = this.requireRun(runId);
        run.cancelled = true;
        run.queuedMessage = null;
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    suspend(runId) {
        const run = this.requireRun(runId);
        run.suspended = true;
        run.queuedMessage = null;
        this.clearFinishTimeout(run);

        return this.ensureTermination(run);
    }

    beginQueuedMessageDraft(runId) {
        return agentInteractions.beginQueuedMessageDraft(this.requireRun(runId));
    }

    setQueuedMessage(runId, sessionId, content, revision) {
        return agentInteractions.setQueuedMessage(this.requireRun(runId), sessionId, content, revision);
    }

    sendQueuedMessage(runId, sessionId, revision) {
        return agentInteractions.sendQueuedMessage(this, this.requireRun(runId), sessionId, revision);
    }

    sendMessage(runId, content) {
        return agentInteractions.sendMessage(this, this.requireStreamingRun(runId), content);
    }

    sendStreamingMessage(run, content) {
        return agentInteractions.sendStreamingMessage(this, run, content);
    }

    answerQuestion(runId, requestId, answers) {
        return agentInteractions.answerQuestion(this, this.requireStreamingRun(runId), requestId, answers);
    }

    answerApproval(runId, requestId, decision) {
        return agentInteractions.answerApproval(this, this.requireStreamingRun(runId), requestId, decision);
    }

    finish(runId) {
        const run = this.requireStreamingRun(runId);
        run.finishing = true;
        run.queuedMessage = null;
        if (!run.turnActive || run.waitingForQuestion) this.beginFinishShutdown(run);
    }

    beginFinishShutdown(run) {
        if (run.finishTimeout !== null && run.finishTimeout !== undefined) return;
        run.finishTimeout = this.setTimeout(this.handleFinishTimeout, AGENT_FINISH_GRACE_MS, run.id);
        run.child.stdin.end();
    }

    clearFinishTimeout(run) {
        if (run.finishTimeout === null || run.finishTimeout === undefined) return;
        this.clearTimeout(run.finishTimeout);
        run.finishTimeout = null;
    }

    async handleFinishTimeout(runId) {
        const run = this.processes.get(runId);
        if (!run) return;
        run.finishTimeout = null;
        console.warn('[agent:finish-timeout]', {
            graceMs: AGENT_FINISH_GRACE_MS,
            pid: run.child.pid,
            runId,
            timestamp: new Date().toISOString(),
        });
        try {
            run.finishForced = await this.ensureTermination(run);
        } catch (error) {
            this.handleError(runId, error);
        }
    }

    stopAll() {
        const completions = [];
        for (const run of this.processes.values()) {
            run.cancelled = true;
            this.clearFinishTimeout(run);
            completions.push(Promise.all([this.ensureTermination(run), run.closed]));
        }

        return Promise.all(completions);
    }

    ensureTermination(run) {
        run.termination ??= this.terminateProcessTree(run.child);

        return run.termination;
    }

    handleCodexRuntimeEvent(event) {
        if (!this.codexRuntimeService) return;
        if (event.kind === 'unavailable') {
            this.codexRuntimeService.publishUnavailable(event.observedAt);
            return;
        }
        this.codexRuntimeService.publishRateLimits(event.payload, event.observedAt, event.kind === 'update');
    }

    handleOutput(runId, channel, chunk) {
        const run = this.processes.get(runId);
        if (!run) return;

        const content = chunk.toString();
        if (channel === 'stdout' && run.protocolLines) {
            run.protocolLines.push(chunk);
            return;
        }
        if (channel === 'stdout' && run.parser) {
            run.parser.push(chunk);
            return;
        }
        if (channel === 'stderr') {
            run.stderrBuffer += content;
            const filtered = filterCompleteStderrLines(run.stderrBuffer);
            run.stderrBuffer = filtered.remainder;
            if (filtered.content.length === 0) return;
            this.recordStderr(run, filtered.content);
            return;
        }
        this.recordOutput(runId, channel, content);
    }

    recordStderr(run, content) {
        const parts = content.split(/(\r\n|\r|\n)/u);
        for (let index = 0; index < parts.length; index += 2) {
            const line = parts[index];
            const delimiter = parts[index + 1] ?? '';
            if (line.length === 0 && delimiter.length === 0) continue;
            if (run.agent !== 'codex' || !isCodexCacheError(line)) {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
                continue;
            }
            if (run.codexCacheErrorReported) continue;
            run.codexCacheErrorReported = true;
            const diagnostic = run.stderrHandling.then(async () => {
                const message = await this.diagnoseCodexCacheError(line, run.executable, run.environment);
                this.recordOutput(run.id, 'stderr', `${message}\n`);
            });
            run.stderrHandling = diagnostic.catch(() => {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
            });
        }
    }

    handleStreamingLine(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        let message;
        try {
            message = JSON.parse(line);
        } catch {
            this.handleMalformedOutput(runId, line);
            return;
        }
        run.protocolHandling = run.protocolHandling
            .then(() => run.streamingAdapter.handleMessage(message))
            .catch((error) => {
                this.failStreamingRun(run, error);
            });
    }

    recordOutput(runId, channel, content) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        const safeContent = redactSecrets(content, run.secretValues);
        if (channel === 'stdout') {
            const { segment } = appendAssistantOutput(run, safeContent, timestamp);
            if (segment.length === 0) return;
            emitRunEvent(run, { content: segment, type: 'output' });
            return;
        }
        run.stderr += safeContent;
        if (run.streaming) {
            emitRunEvent(run, { content: safeContent, type: 'error' });
            return;
        }
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            safeContent,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: safeContent, type: 'error' });
    }

    flushStderr(runId) {
        const run = this.processes.get(runId);
        if (!run || run.stderrBuffer.length === 0) return;

        const content = run.stderrBuffer;
        run.stderrBuffer = '';
        if (!isHiddenStderrLine(content)) this.recordStderr(run, content);
    }

    handleProviderEvent(runId, providerEvent) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        run.turnStarted = run.turnStarted || providerEvent.turnStarted;
        run.missingSession = run.missingSession || providerEvent.missingSession;
        providerEvent.changedPaths.forEach((filePath) => run.changedPaths.add(filePath));
        if (providerEvent.conversationId) run.providerConversationId = providerEvent.conversationId;
        if (providerEvent.usage) run.turnUsage = providerEvent.usage;
        for (const transcriptEvent of providerEvent.transcriptEvents) {
            run.conversation.entries.push(createEventEntry(
                `${runId}-provider-${run.conversation.entries.length}`,
                transcriptEvent.toolType,
                transcriptEvent.content,
                timestamp,
                nextRunSequence(run),
            ));
        }
        if (providerEvent.assistantText.length > 0) {
            const { segment } = appendAssistantOutput(run, providerEvent.assistantText, timestamp);
            if (segment.length > 0) emitRunEvent(run, { content: segment, type: 'output' });
        } else if (providerEvent.errorText.length > 0 && !run.reportedProviderErrors.has(providerEvent.errorText)) {
            const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
            run.reportedProviderErrors.add(providerEvent.errorText);
            run.stderr += `${separator}${providerEvent.errorText}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-error-${run.conversation.entries.length}`,
                'error',
                providerEvent.errorText,
                timestamp,
                nextRunSequence(run),
            ));
            emitRunEvent(run, { content: providerEvent.errorText, type: 'error' });
        }
    }

    async handleStreamingEvent(runId, event) {
        const run = this.processes.get(runId);
        if (!run) return;

        const handler = STREAMING_EVENT_HANDLERS[event.type];
        if (!handler) return;

        await handler(this, run, event, new Date().toISOString());
    }

    handleMalformedOutput(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (!run.streaming) {
            const timestamp = new Date().toISOString();
            const message = `Malformed ${run.agent} JSONL event: ${line}`;
            run.conversation.entries.push(createEventEntry(
                `${runId}-malformed-${run.conversation.entries.length}`,
                'diagnostic',
                message,
                timestamp,
                nextRunSequence(run),
            ));
            return;
        }
        this.failStreamingRun(run, new Error(`Malformed ${run.agent} JSONL event`));
    }

    handleError(runId, error) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (run.streaming) {
            this.failStreamingRun(run, error);
            return;
        }
        const timestamp = new Date().toISOString();
        const message = error instanceof Error ? error.message : 'Agent process failed';
        run.stderr += message;
        run.conversation.entries.push(createEventEntry(
            `${runId}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
    }

    failStreamingRun(run, errorValue) {
        if (run.streamingFailure) return run.termination;

        const error = errorValue instanceof Error ? errorValue : new Error('Streaming agent failed');
        const message = redactSecrets(error.message, run.secretValues);
        const timestamp = new Date().toISOString();
        run.streamingFailure = new Error(message);
        run.conversation.status = 'failed';
        run.queuedMessage = null;
        run.waitingForQuestion = false;
        run.pendingQuestions = [];
        const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
        run.stderr += `${separator}${message}`;
        run.conversation.entries.push(createEventEntry(
            `${run.id}-error-${run.conversation.entries.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
        emitRunEvent(run, { state: 'failed', type: 'state' });
        try {
            run.child.stdin.end();
        } catch {
            // Process-tree termination below remains authoritative.
        }

        return this.ensureTermination(run);
    }

    async handleClose(runId, exitCode) {
        const run = this.processes.get(runId);
        if (!run) return;
        this.clearFinishTimeout(run);

        try {
            if (run.termination) await run.termination;
            run.parser?.finish();
            run.protocolLines?.finish();
            await run.protocolHandling;
            this.flushStderr(runId);
            await run.stderrHandling;
            const completedAt = new Date().toISOString();
            if (run.streaming && !run.finishing && !run.cancelled && !run.streamingFailure && !run.suspended) {
                run.streamingFailure = new Error('Streaming agent process exited before Finish');
                const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
                run.stderr += `${separator}${run.streamingFailure.message}`;
            }
            const succeeded = (exitCode === 0 || (run.finishing && run.finishForced))
                && !run.missingSession
                && !run.cancelled
                && !run.streamingFailure
                && (!run.streaming || run.finishing);
            completeAssistantOutput(run, completedAt);
            if (succeeded) {
                const synchronizedMessage = lastMessageEntry(run.conversation);
                updateProviderSession(run, synchronizedMessage.id, completedAt);
                if (run.turnUsage) run.conversation.usage = accumulateUsage(run.conversation.usage, run.turnUsage);
            }
            const preserveWaitingState = run.suspended && run.conversation.status === 'waitingForInput';
            run.conversation.completedAt = preserveWaitingState ? null : completedAt;
            run.conversation.status = preserveWaitingState
                ? 'waitingForInput'
                : run.cancelled ? 'cancelled' : succeeded ? 'completed' : 'failed';
            const continuedTurnFailedBeforeStart = !!run.request.conversation
                && !run.turnStarted
                && !succeeded
                && !run.cancelled
                && !run.suspended;
            logAgentEvent('[agent:complete]', {
                completedAt,
                durationMs: Date.parse(completedAt) - Date.parse(run.startedAt),
                actionRunId: run.request.actionRunId ?? null,
                exitCode,
                pid: run.child.pid,
                runId,
            });
            await run.persistence;
            if (!continuedTurnFailedBeforeStart) await this.persistConversation(run);
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
            emitRunEvent(run, { conversation: structuredClone(run.conversation), type: 'closed' });
            if (run.onComplete) run.onComplete(succeeded ? 0 : exitCode || 1, run);
        } catch (error) {
            if (run.onCompletionError) run.onCompletionError(error);
        } finally {
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
        }
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: structuredClone(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
}

module.exports = { AGENT_FINISH_GRACE_MS, AgentRunnerService };

