    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
    logs: ActionRunLogEntry[]
    status: ActionRunStatus
}

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.turnStarted = true;
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) run.conversation.usage = accumulateUsage(run.conversation.usage, event.usage);
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
};

module.exports = { STREAMING_EVENT_HANDLERS };

const { normalizeAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const { ClaudeStreamingAdapter } = require('./agent_claude_streaming_adapter');
const { codexChangedPaths } = require('./agent_codex_events');
const { diagnosticEvent, normalizeCodexEvent, systemEvent } = require('./agent_codex_event');
const { isMissingSession } = require('./agent_provider_protocol');

const CODEX_CLIENT_NAME = 'md2';
const CODEX_CLIENT_VERSION = '1';
const CODEX_MISSING_THREAD_ERROR_CODE = -32600;
const CODEX_APPROVAL_METHODS = new Map([
    ['item/commandExecution/requestApproval', 'commandExecution'],
    ['item/fileChange/requestApproval', 'fileChange'],
]);
const CODEX_COMMAND_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_FILE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CODEX_NON_EVENT_ITEM_TYPES = new Set(['agentMessage', 'hookPrompt', 'userMessage']);

function requireMessage(content) {
    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');

    return content;
}

function codexInput(content) {
    return [{ text: requireMessage(content), type: 'text' }];
}

// The app-server already reports cache-free input tokens, unlike `codex exec`, so no subtraction here.
function codexUsage(params) {
    const usage = params.tokenUsage?.last;
    if (!usage) return null;

    return normalizeAgentTokenUsage({
        cachedInputTokens: usage.cachedInputTokens,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        reasoningTokens: usage.reasoningOutputTokens,
    });
}

function ensureEventTextPart(event, field, index) {
    if (!Number.isSafeInteger(index) || index < 0) return;
    while (event[field].length <= index) event[field].push('');
}

function isCodexMissingThreadError(error, providerConversationId) {
    if (!providerConversationId || error?.code !== CODEX_MISSING_THREAD_ERROR_CODE) return false;

    return error.message === `no rollout found for thread id ${providerConversationId}`;
}

function requireCodexApprovalId(value, field) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing Codex approval ${field}`);

    return value;
}

function sameDecision(left, right) {
    return JSON.stringify(left) === JSON.stringify(right);
}

function availableApprovalDecisions(approval) {
    if (approval.kind === 'fileChange') return CODEX_FILE_APPROVAL_DECISIONS;
    if (Array.isArray(approval.availableDecisions)) return approval.availableDecisions;

    return CODEX_COMMAND_APPROVAL_DECISIONS;
}

class CodexStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.onRuntimeEvent = onRuntimeEvent;
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.activeTurnId = null;
        this.activeItems = new Map();
        this.assistantItemOrder = [];
        this.assistantStreams = new Map();
        this.completedItemIds = new Set();
        this.diagnosticSequence = 1;
        this.initialPrompt = null;
        this.nextRequestId = 1;
        this.pendingRequests = new Map();
        this.pendingApprovals = new Map();
        this.threadId = null;
        this.turnUsage = null;
    }

    async start(prompt) {
        this.initialPrompt = requireMessage(prompt);
        await this.sendRequest('initialize', {
            capabilities: { experimentalApi: true },
            clientInfo: { name: CODEX_CLIENT_NAME, version: CODEX_CLIENT_VERSION },
        }, 'initialize');
    }

    async sendMessage(content) {
        const input = codexInput(content);
        if (!this.threadId) throw new Error('Codex streaming thread is not ready');
        if (this.activeTurnId) {
            await this.sendRequest('turn/steer', {
                expectedTurnId: this.activeTurnId,
                input,
                threadId: this.threadId,
            });
            return;
        }
        await this.sendRequest('turn/start', { input, threadId: this.threadId });
    }

    async answerQuestion(requestId, answers) {
        if (requestId === null || requestId === undefined) throw new Error('Missing Codex question request id');
        const normalizedAnswers = Object.fromEntries(Object.entries(answers).map(([questionId, answer]) => [
            questionId,
            { answers: Array.isArray(answer) ? answer : [answer] },
        ]));
        await this.writeLine({ id: requestId, result: { answers: normalizedAnswers } });
    }

    async answerApproval(requestId, decision) {
        const pendingApproval = this.pendingApprovals.get(requestId);
        if (!pendingApproval) throw new Error(`Unknown or stale Codex approval request id: ${requestId}`);
        if (pendingApproval.submitted) throw new Error(`Codex approval request was already submitted: ${requestId}`);
        const availableDecisions = availableApprovalDecisions(pendingApproval.approval);
        if (!availableDecisions.some((availableDecision) => sameDecision(availableDecision, decision))) {
            throw new Error(`Unsupported Codex approval decision for request ${requestId}`);
        }
        pendingApproval.submitted = true;
        try {
            await this.writeLine({ id: requestId, result: { decision } });
        } catch (error) {
            pendingApproval.submitted = false;
            throw error;
        }
        await this.onEvent({ requestId, type: 'approvalSubmitted' });
    }

    async sendRequest(method, params, purpose = null) {
        const id = this.nextRequestId;
        this.nextRequestId += 1;
        if (purpose) this.pendingRequests.set(id, purpose);
        try {
            await this.writeLine({ id, method, params });
        } catch (error) {
            this.pendingRequests.delete(id);
            throw error;
        }
    }

    async handleMessage(message) {
        if (Object.hasOwn(message, 'id') && !message.method) {
            await this.handleResponse(message);
            return;
        }
        if (message.method === 'item/tool/requestUserInput') {
            await this.onEvent({ questions: message.params.questions, requestId: message.id, type: 'question' });
            return;
        }
        if (CODEX_APPROVAL_METHODS.has(message.method)) {
            await this.handleApprovalRequest(message);
            return;
        }
        await this.handleNotification(message.method, message.params ?? {});
    }

    async handleApprovalRequest(message) {
        if (message.id === null || message.id === undefined) throw new Error('Missing Codex approval request id');
        if (this.pendingApprovals.has(message.id)) throw new Error(`Duplicate Codex approval request id: ${message.id}`);
        const kind = CODEX_APPROVAL_METHODS.get(message.method);
        const params = message.params;
        if (!params || typeof params !== 'object' || Array.isArray(params)) throw new Error('Missing Codex approval params');
        const threadId = requireCodexApprovalId(params.threadId, 'thread id');
        const turnId = requireCodexApprovalId(params.turnId, 'turn id');
        const itemId = requireCodexApprovalId(params.itemId, 'item id');
        if (threadId !== this.threadId) throw new Error(`Mismatched Codex approval thread id: ${threadId}`);
        if (turnId !== this.activeTurnId) throw new Error(`Mismatched Codex approval turn id: ${turnId}`);
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== kind || this.completedItemIds.has(itemId)) {
            throw new Error(`Mismatched Codex approval item id: ${itemId}`);
        }
        const filePaths = kind === 'fileChange'
            ? trackedItem.item.changes
                ?.filter(({ path }) => typeof path === 'string' && path.length > 0)
                .map(({ path }) => path) ?? []
            : [];
        const approval = { ...structuredClone(params), filePaths, kind, provider: 'codex', requestId: message.id };
        this.pendingApprovals.set(message.id, { approval, submitted: false });
        await this.onEvent({ approval, type: 'approval' });
    }

    async handleResponse(message) {
        const purpose = this.pendingRequests.get(message.id);
        if (!purpose) {
            if (message.error) await this.onEvent({ content: message.error.message ?? 'Codex request failed', type: 'fatal' });
            return;
        }
        this.pendingRequests.delete(message.id);
        if (message.error) {
            const content = message.error.message ?? `Codex ${purpose} failed`;
            if (purpose === 'rateLimitsRead') {
                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: Date.now() });
                return;
            }
            if (purpose === 'threadResume') {
                const missingSession = isCodexMissingThreadError(message.error, this.providerConversationId)
                    || isMissingSession('codex', { error: message.error, type: 'error' }, false);
                await this.onEvent({ content, missingSession, type: 'sessionFailed' });
                return;
            }
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (purpose === 'initialize') {
            await this.writeLine({ method: 'initialized', params: {} });
            await this.sendRequest('account/rateLimits/read', undefined, 'rateLimitsRead');
            if (this.providerConversationId) {
                await this.sendRequest('thread/resume', {
                    cwd: this.rootPath,
                    threadId: this.providerConversationId,
                }, 'threadResume');
                return;
            }
            await this.sendRequest('thread/start', { cwd: this.rootPath }, 'threadStart');
            return;
        }
        if (purpose === 'threadStart' || purpose === 'threadResume') {
            this.threadId = message.result?.thread?.id ?? message.result?.threadId ?? this.providerConversationId;
            if (!this.threadId) throw new Error('Codex app-server did not return a thread id');
            await this.onEvent({ conversationId: this.threadId, type: 'sessionStarted' });
            await this.sendMessage(this.initialPrompt);
            return;
        }
        if (purpose === 'rateLimitsRead') {
            const hasSingleBucket = !!message.result?.rateLimits && typeof message.result.rateLimits === 'object';
            const hasBuckets = !!message.result?.rateLimitsByLimitId
                && typeof message.result.rateLimitsByLimitId === 'object'
                && Object.keys(message.result.rateLimitsByLimitId).length > 0;
            await this.onRuntimeEvent(hasSingleBucket || hasBuckets
                ? { kind: 'snapshot', observedAt: Date.now(), payload: message.result }
                : { kind: 'unavailable', observedAt: Date.now() });
        }
    }

    async handleNotification(method, params) {
        if (method === 'turn/started') {
            this.activeItems.clear();
            this.assistantItemOrder = [];
            this.assistantStreams.clear();
            this.completedItemIds.clear();
            this.activeTurnId = params.turn?.id ?? params.turnId;
            await this.onEvent({ turnId: this.activeTurnId, type: 'turnStarted' });
            return;
        }
        if (method === 'serverRequest/resolved') {
            await this.handleApprovalResolved(params);
            return;
        }
        if (method === 'item/started') {
            await this.handleItemStarted(method, params.item);
            return;
        }
        if (method === 'item/agentMessage/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'agentMessage');
            if (!trackedItem) return;
            trackedItem.assistantText = trackedItem.assistantText || params.delta.length > 0;
            trackedItem.bufferedAssistantText += params.delta;
            await this.flushAssistantStreams();
            return;
        }
        if (method === 'item/reasoning/summaryTextDelta') {
            await this.handleReasoningDelta(method, params, 'summary', params.summaryIndex);
            return;
        }
        if (method === 'item/reasoning/summaryPartAdded') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
            if (!trackedItem) return;
            ensureEventTextPart(trackedItem.event, 'summary', params.summaryIndex);
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/reasoning/textDelta') {
            await this.handleReasoningDelta(method, params, 'details', params.contentIndex);
            return;
        }
        if (method === 'item/commandExecution/outputDelta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'commandExecution');
            if (!trackedItem) return;
            trackedItem.event.output += params.delta;
            trackedItem.event.content = trackedItem.event.output;
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'item/plan/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'plan');
            if (!trackedItem) return;
            trackedItem.event.content += params.delta;
            await this.emitEvent(trackedItem.event);
            return;
        }
        if (method === 'thread/tokenUsage/updated') {
            this.turnUsage = codexUsage(params);
            return;
        }
        if (method === 'account/rateLimits/updated') {
            await this.onRuntimeEvent({ kind: 'update', observedAt: Date.now(), payload: params });
            return;
        }
        if (method === 'item/completed') {
            await this.handleItemCompleted(method, params.item);
            return;
        }
        const normalizedSystemEvent = systemEvent(method, params);
        if (normalizedSystemEvent) {
            await this.emitEvent(normalizedSystemEvent);
            return;
        }
        if (method === 'error') {
            const content = params.error?.message ?? 'Codex turn failed';
            await this.emitEvent({
                content,
                label: 'Turn failure',
                providerItemId: `system:${this.activeTurnId ?? 'unknown-turn'}:error`,
                status: 'failed',
                type: 'system',
            });
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (method === 'turn/completed') {
            const error = params.turn?.status === 'failed'
                ? params.turn.error?.message ?? 'Codex turn failed'
                : null;
            if (error) {
                await this.emitEvent({
                    content: error,
                    label: 'Turn failure',
                    providerItemId: `system:${params.turn?.id ?? this.activeTurnId ?? 'unknown-turn'}:turn/completed`,
                    status: 'failed',
                    type: 'system',
                });
            }
            const completedTurnId = params.turn?.id ?? this.activeTurnId;
            await this.resolveApprovalsForTurn(completedTurnId);
            this.activeTurnId = null;
            await this.onEvent({ error, type: 'turnCompleted', usage: this.turnUsage });
            this.turnUsage = null;
            return;
        }
        if (method?.startsWith('item/') && typeof params.itemId === 'string') {
            await this.emitDiagnostic(method, null, params.itemId);
        }
    }

    async handleApprovalResolved(params) {
        const pendingApproval = this.pendingApprovals.get(params.requestId);
        if (!pendingApproval) return;
        if (params.threadId !== pendingApproval.approval.threadId) {
            throw new Error(`Mismatched Codex approval resolution thread id: ${params.threadId}`);
        }
        this.pendingApprovals.delete(params.requestId);
        await this.onEvent({ requestId: params.requestId, type: 'approvalResolved' });
    }

    async resolveApprovalsForTurn(turnId) {
        for (const [requestId, pendingApproval] of this.pendingApprovals) {
            if (pendingApproval.approval.turnId !== turnId) continue;
            this.pendingApprovals.delete(requestId);
            await this.onEvent({ requestId, type: 'approvalResolved' });
        }
    }

    async handleItemStarted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.activeItems.has(item.id) || this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const event = normalizeCodexEvent(item, 'inProgress');
        const knownNonEvent = CODEX_NON_EVENT_ITEM_TYPES.has(item.type);
        const trackedItem = {
            event,
            assistantCompleted: false,
            assistantText: false,
            bufferedAssistantText: '',
            item: structuredClone(item),
            itemType: item.type,
        };
        this.activeItems.set(item.id, trackedItem);
        if (item.type === 'agentMessage') {
            this.assistantItemOrder.push(item.id);
            this.assistantStreams.set(item.id, trackedItem);
            await this.onEvent({ itemId: item.id, type: 'assistantStarted' });
        }
        if (event) {
            await this.emitEvent(event);
            return;
        }
        if (!knownNonEvent) await this.emitDiagnostic(method, item.type, item.id);
    }

    async handleItemCompleted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const trackedItem = this.activeItems.get(item.id);
        if (!trackedItem) await this.emitDiagnostic(method, item.type, item.id);
        if (trackedItem && trackedItem.itemType !== item.type) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        if (item.type === 'agentMessage' && trackedItem) {
            trackedItem.assistantCompleted = true;
            await this.flushAssistantStreams();
        }
        const changedPaths = codexChangedPaths(item, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        const event = normalizeCodexEvent(item, 'completed');
        if (event) await this.emitEvent(event);
        if (!event && !CODEX_NON_EVENT_ITEM_TYPES.has(item.type) && trackedItem) {
            await this.emitDiagnostic(method, item.type, item.id);
        }
        this.activeItems.delete(item.id);
        this.completedItemIds.add(item.id);
    }

    async requireActiveItem(method, itemId, expectedType) {
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== expectedType || this.completedItemIds.has(itemId)) {
            await this.emitDiagnostic(method, expectedType, itemId);

            return null;
        }

        return trackedItem;
    }

    async handleReasoningDelta(method, params, field, index) {
        const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
        if (!trackedItem || !Number.isSafeInteger(index) || index < 0) {
            if (trackedItem) await this.emitDiagnostic(method, 'reasoning', params.itemId);
            return;
        }
        ensureEventTextPart(trackedItem.event, field, index);
        trackedItem.event[field][index] += params.delta;
        trackedItem.event.content = trackedItem.event.summary.length > 0
            ? trackedItem.event.summary.join('\n\n')
            : trackedItem.event.details.join('\n\n');
        await this.emitEvent(trackedItem.event);
    }

    async flushAssistantStreams() {
        while (this.assistantItemOrder.length > 0) {
            const itemId = this.assistantItemOrder[0];
            const stream = this.assistantStreams.get(itemId);
            if (!stream) {
                this.assistantItemOrder.shift();
                continue;
            }
            if (stream.bufferedAssistantText.length > 0) {
                const content = stream.bufferedAssistantText;
                stream.bufferedAssistantText = '';
                await this.onEvent({ content, itemId, type: 'assistant' });
            }
            if (!stream.assistantCompleted) return;
            if (stream.assistantText) await this.onEvent({ content: '\n\n', itemId, type: 'assistant' });
            this.assistantStreams.delete(itemId);
            this.assistantItemOrder.shift();
        }
    }

    async emitEvent(event) {
        await this.onEvent({ event: structuredClone(event), type: 'event' });
    }

    async emitDiagnostic(method, itemType, itemId) {
        const event = diagnosticEvent(method, itemType, itemId, this.diagnosticSequence);
        this.diagnosticSequence += 1;
        await this.emitEvent(event);
    }
}

function createAgentStreamingAdapter(
    agent,
    writeLine,
    onEvent,
    rootPath,
    providerConversationId = null,
    onRuntimeEvent = async () => undefined,
) {
    if (agent === 'claude') return new ClaudeStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId);
    if (agent === 'codex') {
        return new CodexStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent);
    }

    throw new Error(`Agent profile does not support streaming: ${agent}`);
}

module.exports = { createAgentStreamingAdapter };

const { normalizedContent } = require('./agent_event_utils');
const { claudeChangedPaths, claudeUsage } = require('./agent_claude_events');
const { isMissingSession } = require('./agent_provider_protocol');

const CLAUDE_APPROVAL_DECISIONS = ['accept', 'acceptForSession', 'decline', 'cancel'];
const CLAUDE_FILE_TOOLS = new Set(['Edit', 'MultiEdit', 'NotebookEdit', 'Write']);
const CLAUDE_QUESTION_TOOL = 'AskUserQuestion';

function requireMessage(content) {
    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');

    return content;
}

function claudeUserMessage(content) {
    return { message: { content, role: 'user' }, type: 'user' };
}

function claudeControlResponse(requestId, response) {
    return {
        response: { request_id: requestId, response, subtype: 'success' },
        type: 'control_response',
    };
}

function claudeQuestionRequest(event) {
    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
    if (event.request.tool_name !== CLAUDE_QUESTION_TOOL || !Array.isArray(event.request.input?.questions)) return null;

    const questions = event.request.input.questions.map((question, index) => ({
        ...question,
        id: question.id ?? `claude-question-${index}`,
    }));

    return {
        input: event.request.input,
        questions,
        requestId: event.request_id,
        toolUseId: event.request.tool_use_id,
    };
}

function approvalFilePaths(toolName, input) {
    if (!CLAUDE_FILE_TOOLS.has(toolName) || !input || typeof input !== 'object' || Array.isArray(input)) return [];
    const filePath = toolName === 'NotebookEdit' ? input.notebook_path : input.file_path;

    return typeof filePath === 'string' && filePath.length > 0 ? [filePath] : [];
}

function claudeApprovalRequest(event) {
    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
    if (event.request.tool_name === CLAUDE_QUESTION_TOOL) return null;
    const { input, permission_suggestions: permissionSuggestions, tool_name: toolName, tool_use_id: toolUseId } = event.request;
    if (event.request_id === undefined || event.request_id === null) throw new Error('Missing Claude approval request id');
    if (typeof toolName !== 'string' || toolName.length === 0) throw new Error('Missing Claude approval tool name');
    if (typeof toolUseId !== 'string' || toolUseId.length === 0) throw new Error('Missing Claude approval tool use id');
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Missing Claude approval input');
    if (permissionSuggestions !== undefined && !Array.isArray(permissionSuggestions)) {
        throw new Error('Invalid Claude approval permission suggestions');
    }
    const availableDecisions = permissionSuggestions?.length > 0
        ? CLAUDE_APPROVAL_DECISIONS
        : CLAUDE_APPROVAL_DECISIONS.filter((decision) => decision !== 'acceptForSession');
    const approval = {
        approvalId: toolUseId,
        availableDecisions,
        command: toolName === 'Bash' && typeof input.command === 'string' ? input.command : null,
        cwd: typeof input.cwd === 'string' ? input.cwd : null,
        filePaths: approvalFilePaths(toolName, input),
        input: structuredClone(input),
        itemId: toolUseId,
        kind: toolName === 'Bash' ? 'commandExecution' : CLAUDE_FILE_TOOLS.has(toolName) ? 'fileChange' : 'toolUse',
        permissionSuggestions: structuredClone(permissionSuggestions ?? []),
        provider: 'claude',
        reason: event.request.decision_reason ?? event.request.reason ?? null,
        requestId: event.request_id,
        startedAtMs: Date.now(),
        toolName,
    };

    return { approval, input, permissionSuggestions: permissionSuggestions ?? [], toolUseId };
}

function claudeApprovalResponse(pendingApproval, decision) {
    const { input, permissionSuggestions, toolUseId } = pendingApproval;
    if (decision === 'accept') return { behavior: 'allow', toolUseID: toolUseId, updatedInput: input };
    if (decision === 'acceptForSession') {
        return {
            behavior: 'allow',
            toolUseID: toolUseId,
            updatedInput: input,
            updatedPermissions: permissionSuggestions,
        };
    }
    if (decision === 'decline') {
        return { behavior: 'deny', message: 'User declined this tool request', toolUseID: toolUseId };
    }

    return { behavior: 'deny', interrupt: true, message: 'User stopped the turn', toolUseID: toolUseId };
}

function isClaudeMissingSessionResult(event, providerConversationId) {
    if (!providerConversationId || event.type !== 'result' || event.is_error !== true) return false;
    if (event.session_id !== providerConversationId || !Array.isArray(event.errors)) return false;

    return event.errors.includes(`No conversation found with session ID: ${providerConversationId}`);
}

function eventBase(providerItemId, type, label, status = 'inProgress') {
    return { content: '', label, providerItemId, status, type };
}

function toolInputContent(input) {
    if (typeof input === 'string') return input;

    return JSON.stringify(input ?? {});
}

function claudeToolEvent(block, status = 'inProgress', providerItemId = block.id) {
    const base = eventBase(providerItemId, `tool.${block.name}`, block.name, status);
    if (block.name === 'Bash') {
        return {
            ...base,
            command: block.input?.command,
            content: block.input?.command ?? toolInputContent(block.input),
            label: block.input?.command ?? 'Bash',
            type: 'commandExecution',
            workingDirectory: block.input?.cwd,
        };
    }
    if (CLAUDE_FILE_TOOLS.has(block.name)) {
        const filePaths = approvalFilePaths(block.name, block.input);
        const content = typeof block.input === 'string' ? block.input : filePaths.join('\n');

        return { ...base, content, label: block.name, type: 'fileChange' };
    }

    return { ...base, content: toolInputContent(block.input) };
}

class ClaudeStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.pendingApprovals = new Map();
        this.pendingQuestions = new Map();
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.activeBlocks = new Map();
        this.streamedTextItems = new Map();
        this.activeMessageId = null;
        this.protocolErrorSequence = 1;
        this.turnStarted = false;
        this.turnHasAssistantText = false;
    }

    async start(prompt) {
        await this.sendMessage(prompt);
    }

    async sendMessage(content) {
        await this.writeLine(claudeUserMessage(requireMessage(content)));
    }

    async answerQuestion(requestId, answers) {
        const pendingQuestion = this.pendingQuestions.get(requestId);
        if (!pendingQuestion) throw new Error(`Unknown Claude question request id: ${requestId}`);
        const mappedAnswers = Object.fromEntries(pendingQuestion.questions.map(({ id, question }) => {
            if (!Object.hasOwn(answers, id)) throw new Error(`Missing answer for Claude question: ${id}`);

            return [question, answers[id]];
        }));
        const updatedInput = { ...pendingQuestion.input, answers: mappedAnswers };
        const response = { behavior: 'allow', toolUseID: pendingQuestion.toolUseId, updatedInput };
        await this.writeLine(claudeControlResponse(requestId, response));
        this.pendingQuestions.delete(requestId);
    }

    async answerApproval(requestId, decision) {
        const pendingApproval = this.pendingApprovals.get(requestId);
        if (!pendingApproval) throw new Error(`Unknown or stale Claude approval request id: ${requestId}`);
        if (pendingApproval.submitted) throw new Error(`Claude approval request was already submitted: ${requestId}`);
        if (!pendingApproval.approval.availableDecisions.includes(decision)) {
            throw new Error(`Unsupported Claude approval decision for request ${requestId}`);
        }
        const response = claudeApprovalResponse(pendingApproval, decision);
        pendingApproval.submitted = true;
        try {
            await this.writeLine(claudeControlResponse(requestId, response));
        } catch (error) {
            pendingApproval.submitted = false;
            throw error;
        }
        await this.onEvent({ requestId, type: 'approvalSubmitted' });
        this.pendingApprovals.delete(requestId);
        await this.onEvent({ requestId, type: 'approvalResolved' });
    }

    async handleMessage(event) {
        const questionRequest = claudeQuestionRequest(event);
        if (questionRequest) {
            this.pendingQuestions.set(questionRequest.requestId, questionRequest);
            await this.onEvent({
                questions: questionRequest.questions,
                requestId: questionRequest.requestId,
                type: 'question',
            });
            return;
        }
        const approvalRequest = claudeApprovalRequest(event);
        if (approvalRequest) {
            if (this.pendingApprovals.has(approvalRequest.approval.requestId)) {
                throw new Error(`Duplicate Claude approval request id: ${approvalRequest.approval.requestId}`);
            }
            this.pendingApprovals.set(approvalRequest.approval.requestId, { ...approvalRequest, submitted: false });
            await this.onEvent({ approval: approvalRequest.approval, type: 'approval' });
            return;
        }
        if (event.type === 'control_request' && event.request?.subtype === 'can_use_tool') {
            throw new Error('Invalid Claude question request');
        }
        if (event.type === 'system' && typeof event.session_id === 'string') {
            await this.onEvent({ conversationId: event.session_id, type: 'sessionStarted' });
        }
        if (event.type === 'system') {
            if (event.subtype !== 'init') ClaudeStreamingAdapter.ignoreProtocolNoise();
            return;
        }
        if (event.type === 'stream_event') {
            await this.handleStreamEvent(event.event);
            return;
        }
        if (event.type === 'assistant') {
            await this.handleAssistantCompletion(event);
            return;
        }
        if (event.type === 'user') {
            await this.ensureTurnStarted();
            await this.handleToolResults(event);
            return;
        }
        if (event.type === 'result') {
            await this.handleResult(event);
            return;
        }
        ClaudeStreamingAdapter.ignoreProtocolNoise();
    }

    async ensureTurnStarted() {
        if (this.turnStarted) return;
        this.turnStarted = true;
        await this.onEvent({ type: 'turnStarted' });
    }

    async handleStreamEvent(streamEvent) {
        if (!streamEvent || typeof streamEvent.type !== 'string') {
            await this.emitProtocolError('invalid stream event');
            return;
        }
        if (streamEvent.type === 'message_start') {
            await this.ensureTurnStarted();
            this.activeMessageId = streamEvent.message?.id;
            this.activeBlocks.clear();
            if (typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
                await this.emitProtocolError('message_start missing message id');
            }
            return;
        }
        if (streamEvent.type === 'content_block_start') {
            await this.handleContentBlockStart(streamEvent);
            return;
        }
        if (streamEvent.type === 'content_block_delta') {
            await this.handleContentBlockDelta(streamEvent);
            return;
        }
        if (streamEvent.type === 'content_block_stop' || streamEvent.type === 'message_delta' || streamEvent.type === 'message_stop') return;
        ClaudeStreamingAdapter.ignoreProtocolNoise();
    }

    async handleContentBlockStart(streamEvent) {
        const validBlock = !!streamEvent.content_block
            && typeof streamEvent.content_block === 'object'
            && !Array.isArray(streamEvent.content_block);
        if (!Number.isSafeInteger(streamEvent.index) || !validBlock || typeof this.activeMessageId !== 'string' || this.activeMessageId.length === 0) {
            await this.emitProtocolError('invalid content_block_start');
            return;
        }
        const block = structuredClone(streamEvent.content_block);
        const providerItemId = block.id ?? `${this.activeMessageId}:${block.type}:${streamEvent.index}`;
        const separator = block.type === 'text' && this.turnHasAssistantText ? '\n\n' : '';
        const trackedBlock = { block, inputJson: '', providerItemId, separator, text: block.text ?? block.thinking ?? '' };
        this.activeBlocks.set(streamEvent.index, trackedBlock);
        if (block.type === 'text') {
            // Keyed by stable providerItemId so the later aggregated `assistant` message reconciles
            // even after `message_start` of the next step has cleared `activeBlocks`.
            this.streamedTextItems.set(providerItemId, { separator });
            await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
            if (separator.length > 0) await this.onEvent({ content: separator, itemId: providerItemId, type: 'assistant' });
            return;
        }
        if (block.type === 'thinking') {
            const event = {
                ...eventBase(providerItemId, 'reasoning', 'Thinking'),
                content: trackedBlock.text,
                details: [trackedBlock.text],
                summary: [],
            };
            await this.onEvent({ event, type: 'event' });
            return;
        }
        if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
    }

    async handleContentBlockDelta(streamEvent) {
        const trackedBlock = this.activeBlocks.get(streamEvent.index);
        if (!trackedBlock || !streamEvent.delta || typeof streamEvent.delta.type !== 'string') {
            await this.emitProtocolError('invalid content_block_delta');
            return;
        }
        const { delta } = streamEvent;
        if (delta.type === 'text_delta' && typeof delta.text === 'string' && trackedBlock.block.type === 'text') {
            trackedBlock.text += delta.text;
            this.turnHasAssistantText = this.turnHasAssistantText || delta.text.length > 0;
            await this.onEvent({ content: delta.text, itemId: trackedBlock.providerItemId, type: 'assistant' });
            return;
        }
        if (delta.type === 'thinking_delta' && typeof delta.thinking === 'string' && trackedBlock.block.type === 'thinking') {
            trackedBlock.text += delta.thinking;
            const event = {
                ...eventBase(trackedBlock.providerItemId, 'reasoning', 'Thinking'),
                content: trackedBlock.text,
                details: [trackedBlock.text],
                summary: [],
            };
            await this.onEvent({ event, type: 'event' });
            return;
        }
        if (delta.type === 'input_json_delta' && typeof delta.partial_json === 'string' && trackedBlock.block.type === 'tool_use') {
            trackedBlock.inputJson += delta.partial_json;
            const updatedBlock = { ...trackedBlock.block, input: trackedBlock.inputJson };
            await this.onEvent({ event: claudeToolEvent(updatedBlock, 'inProgress', trackedBlock.providerItemId), type: 'event' });
            return;
        }
        if (delta.type !== 'signature_delta') ClaudeStreamingAdapter.ignoreProtocolNoise();
    }

    async handleAssistantCompletion(event) {
        await this.ensureTurnStarted();
        if (!Array.isArray(event.message?.content)) {
            await this.emitProtocolError('assistant message missing content');
            return;
        }
        const messageId = event.message.id ?? this.activeMessageId;
        if (typeof messageId !== 'string' || messageId.length === 0) throw new Error('Missing Claude assistant message id');
        for (const [index, block] of event.message.content.entries()) {
            const providerItemId = block.id ?? `${messageId}:${block.type}:${index}`;
            if (block.type === 'text' && typeof block.text === 'string') {
                const streamedItem = this.streamedTextItems.get(providerItemId);
                const separator = streamedItem?.separator ?? (this.turnHasAssistantText ? '\n\n' : '');
                if (!streamedItem) {
                    await this.onEvent({ itemId: providerItemId, type: 'assistantStarted' });
                }
                this.turnHasAssistantText = this.turnHasAssistantText || block.text.length > 0;
                await this.onEvent({ content: `${separator}${block.text}`, itemId: providerItemId, type: 'assistantCompleted' });
                continue;
            }
            if (block.type === 'thinking') {
                const content = typeof block.thinking === 'string' ? block.thinking : '';
                const reasoningEvent = {
                    ...eventBase(providerItemId, 'reasoning', 'Thinking', 'completed'),
                    content,
                    details: [content],
                    summary: [],
                };
                await this.onEvent({ event: reasoningEvent, type: 'event' });
                continue;
            }
            if (block.type === 'tool_use') await this.onEvent({ event: claudeToolEvent(block, 'inProgress', providerItemId), type: 'event' });
        }
        const changedPaths = claudeChangedPaths(event, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
    }

    async handleToolResults(event) {
        if (!Array.isArray(event.message?.content)) return;
        for (const block of event.message.content) {
            if (block?.type !== 'tool_result' || typeof block.tool_use_id !== 'string') continue;
            const trackedTool = [...this.activeBlocks.values()].find(({ providerItemId }) => providerItemId === block.tool_use_id);
            const toolEvent = trackedTool?.block?.type === 'tool_use'
                ? claudeToolEvent(trackedTool.block, block.is_error ? 'failed' : 'completed')
                : eventBase(block.tool_use_id, 'tool.result', 'Tool result', block.is_error ? 'failed' : 'completed');
            toolEvent.output = normalizedContent(block.content) ?? '';
            await this.onEvent({ event: toolEvent, type: 'event' });
        }
    }

    async handleResult(event) {
        const error = event.is_error === true
            ? String(event.error ?? event.result ?? event.message ?? event.errors?.join('\n') ?? 'Claude turn failed')
            : null;
        const missingSession = !this.turnStarted && (
            isClaudeMissingSessionResult(event, this.providerConversationId)
            || isMissingSession('claude', event, this.turnStarted)
        );
        for (const requestId of this.pendingApprovals.keys()) {
            this.pendingApprovals.delete(requestId);
            await this.onEvent({ requestId, type: 'approvalResolved' });
        }
        this.activeBlocks.clear();
        this.streamedTextItems.clear();
        this.activeMessageId = null;
        this.pendingQuestions.clear();
        this.turnStarted = false;
        this.turnHasAssistantText = false;
        await this.onEvent({ error, missingSession, type: 'turnCompleted', usage: claudeUsage(event) });
    }

    static ignoreProtocolNoise() {
        // Valid protocol additions need no user-facing event until adapter support exists.
    }

    async emitProtocolError(content) {
        const providerItemId = `error:${this.activeMessageId ?? 'unknown-message'}:${this.protocolErrorSequence}`;
        this.protocolErrorSequence += 1;
        const event = { ...eventBase(providerItemId, 'error', 'Claude protocol error', 'failed'), content };
        await this.onEvent({ event, type: 'event' });
    }
}

module.exports = { ClaudeStreamingAdapter };

