import { useCallback, useSyncExternalStore } from 'react'
import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import { actionRunRegistry, type ActionRun, type ActionRunStore } from '../../services/actions/action_run_registry'

const EMPTY_ACTIVE_RUNS: ReturnType<typeof actionRunRegistry.getGlobalActiveSnapshot> = []
const subscribeEmpty = () => () => undefined
const getNullSnapshot = () => null

function useRunStore<T>(store: ActionRunStore | null, selector: (run: ActionRun | null) => T) {
    return useSyncExternalStore(
        store?.subscribe ?? subscribeEmpty,
        () => selector(store?.getSnapshot() ?? null),
        () => selector(null),
    )
}

function useActionRunStore(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoreByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )
    const store = useSyncExternalStore(
        subscribe,
        getSnapshot,
        getNullSnapshot,
    )

    return store
}

/** Subscribe to only the latest run bound to one root action and context. */
export function useActionRun(actionId: string, context: ActionContext) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, (run) => run)
}

/** Subscribe to one selected value from a scoped action run. */
export function useActionRunSelector<T>(actionId: string, context: ActionContext, selector: (run: ActionRun | null) => T) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, selector)
}

/** Subscribe to active run status summaries for one context. */
export function useActiveActionRunsForContext(context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeContextActiveByKey(contextIdentity, listener),
        [contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getContextActiveSnapshotByKey(contextIdentity),
        [contextIdentity],
    )

    return useSyncExternalStore(
        subscribe,
        getSnapshot,
        () => EMPTY_ACTIVE_RUNS,
    )
}

export function useRunningActionForContext(context: ActionContext) {
    return useActiveActionRunsForContext(context)[0] ?? null
}

/** Subscribe to the global active-run aggregate used by the global indicator. */
export function useActiveActionRuns() {
    return useSyncExternalStore(
        actionRunRegistry.subscribeGlobalActive,
        actionRunRegistry.getGlobalActiveSnapshot,
        actionRunRegistry.getGlobalActiveSnapshot,
    )
}

import type { ActionContext } from './action_context'
import type { AgentConversation, AgentConversationEventEntry, AgentConversationMessageEntry } from './data_types'
import type { PermissionMode, ThinkingLevel } from './agent_profiles'
import type { ActionAutoFinish, ActionType } from './action_types'

export type ActionRunTerminalStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'
export type ActionRunStatus = ActionRunTerminalStatus | 'queued' | 'running' | 'waitingForInput'
export type ActionRunPhase = 'after' | 'before' | 'main' | 'on'

export interface ActionRunInput {
    agent?: string
    continueFrom?: string
    extraPrompt?: string
    model?: string
    permissionMode?: PermissionMode
    prompt?: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionPromptRequest {
    actionId: string
    context: ActionContext
}

export interface PreparedActionPrompt {
    prompt: string
}

export interface AgentConversationReservation {
    conversationId: string
    reference: string
}

export interface ActionStartRequest {
    actionId: string
    conversationReservation?: AgentConversationReservation
    context: ActionContext
    runInput: ActionRunInput
}

export interface AgentQuestionOption {
    description?: string
    label: string
}

export interface AgentQuestion {
    header: string
    id: string
    isOther?: boolean
    isSecret?: boolean
    options?: AgentQuestionOption[] | null
    question: string
}

export type AgentApprovalRequestId = number | string
export type AgentNetworkProtocol = 'http' | 'https' | 'socks5Tcp' | 'socks5Udp'
export type AgentFileSystemPath =
    | { path: string, type: 'path' }
    | { pattern: string, type: 'glob_pattern' }
    | { type: 'special', value: string }
export interface AgentAdditionalPermissions {
    fileSystem: {
        entries?: { access: 'deny' | 'read' | 'write', path: AgentFileSystemPath }[]
        read: string[] | null
        write: string[] | null
    } | null
    network: { enabled: boolean | null } | null
}
export type AgentCommandAction =
    | { command: string, name: string, path: string, type: 'read' }
    | { command: string, path: string | null, type: 'listFiles' }
    | { command: string, path: string | null, query: string | null, type: 'search' }
    | { command: string, type: 'unknown' }
export interface AgentNetworkPolicyAmendment {
    action: 'allow' | 'deny'
    host: string
}
export type AgentApprovalDecision =
    | 'accept'
    | 'acceptForSession'
    | 'cancel'
    | 'decline'
    | { acceptWithExecpolicyAmendment: { execpolicy_amendment: string[] } }
    | { applyNetworkPolicyAmendment: { network_policy_amendment: AgentNetworkPolicyAmendment } }
export interface AgentApproval {
    additionalPermissions?: AgentAdditionalPermissions | null
    approvalId?: string | null
    availableDecisions?: AgentApprovalDecision[] | null
    command?: string | null
    commandActions?: AgentCommandAction[] | null
    cwd?: string | null
    environmentId?: string | null
    filePaths: string[]
    grantRoot?: string | null
    input?: Record<string, unknown> | null
    itemId: string
    kind: 'commandExecution' | 'fileChange' | 'toolUse'
    networkApprovalContext?: { host: string, protocol: AgentNetworkProtocol } | null
    proposedExecpolicyAmendment?: string[] | null
    proposedNetworkPolicyAmendments?: AgentNetworkPolicyAmendment[] | null
    provider?: 'claude' | 'codex'
    permissionSuggestions?: unknown[] | null
    reason?: string | null
    requestId: AgentApprovalRequestId
    startedAtMs: number
    threadId?: string
    toolName?: string | null
    turnId?: string
}

interface ActionRunEventBase {
    actionId: string
    actionType?: ActionType
    autoFinish?: ActionAutoFinish | null
    context: ActionContext
    runId: string
    interactionReady?: boolean
    phase: ActionRunPhase
    rootActionId: string
    sequence?: number
    streaming?: boolean
}

export type ActionRunUpdate =
    | {
        continued?: boolean
        conversation: AgentConversation
        kind: 'agentStarted'
    }
    | {
        conversation: AgentConversation
        kind: 'agentClosed'
    }
    | {
        kind: 'agentQuestion'
        questions: AgentQuestion[]
        requestId: number | string | null
    }
    | {
        approval: AgentApproval
        kind: 'agentApproval'
    }
    | {
        kind: 'agentApprovalResolved' | 'agentApprovalSubmitted'
        requestId: AgentApprovalRequestId
    }
    | {
        kind: 'agentQuestionAnswer' | 'agentUserMessage'
        userMessage: AgentConversationMessageEntry
    }
    | {
        event: AgentConversationEventEntry
        kind: 'agentEvent'
    }
    | {
        command?: string
        content: string
        kind: 'error' | 'output'
        messageId?: string
        previousContent?: string
        replace?: boolean
        sequence?: number
    }

export type ActionRunEvent =
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
        permissionMode?: PermissionMode
        reference?: string
        status: ActionRunStatus
        thinkingLevel?: ThinkingLevel
        type: 'action'
    }
    | ActionRunEventBase & {
        status: 'running' | 'waitingForInput'
        type: 'agentState'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'update'
        update: ActionRunUpdate
    }

export interface ActionRunLogEntry {
    actionId: string
    actionName: string
    command: string | null
    message: string
    phase: ActionRunPhase
    permissionMode?: PermissionMode
    status: ActionRunStatus
    stderr: string
    stdout: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
    logs: ActionRunLogEntry[]
    status: ActionRunStatus
}

const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.turnStarted = true;
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) run.conversation.usage = accumulateUsage(run.conversation.usage, event.usage);
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
